import React from "react";
import { AbsoluteFill, Img, staticFile, useCurrentFrame } from "remotion";

export const fps = 25;
// Seamless idle loop, no entrance animation. Longer loop = slower drift.
export const durationInFrames = 3000; // 120s

const DOT_COLOR = "#84300A";

const VB_WIDTH = 3846;
const VB_HEIGHT = 2459;

// DENSITY > 1 packs the dots closer together (smaller gaps). The motif shape is
// preserved exactly — it's just a uniformly tighter version of the same grid.
const DENSITY = 1.5;
const TILE_W = 269.64 / DENSITY;
const TILE_H = 224.7 / DENSITY;
const SCALE = 3.21 / DENSITY; // scales the 3x3 dot motif within each tile
const DOT_R = 3.21; // dot radius stays constant so dots don't shrink

const DOT_OFFSETS_PATTERN: Array<[number, number]> = [
  [7, 7], [7, 30], [7, 52],
  [36, 7], [36, 30], [36, 52],
  [65, 7], [65, 30], [65, 52],
];

const DOTS: Array<{ x: number; y: number }> = (() => {
  const out: Array<{ x: number; y: number }> = [];
  const cols = Math.ceil(VB_WIDTH / TILE_W) + 1;
  const rows = Math.ceil(VB_HEIGHT / TILE_H) + 1;
  for (let ty = 0; ty < rows; ty++) {
    for (let tx = 0; tx < cols; tx++) {
      for (const [px, py] of DOT_OFFSETS_PATTERN) {
        const x = tx * TILE_W + px * SCALE;
        const y = ty * TILE_H + py * SCALE;
        if (x < 0 || x > VB_WIDTH || y < 0 || y > VB_HEIGHT) continue;
        out.push({ x, y });
      }
    }
  }
  return out;
})();

// --- Idle "cursor" interaction -------------------------------------------
// A virtual pointer slowly wanders the canvas on a periodic path so the whole
// minute loops seamlessly. Dots near the pointer are gently nudged away, as if
// a mouse were gliding across them. Only the region near the pointer reacts;
// everything else stays put, exactly like a real cursor passing over them.
const TAU = Math.PI * 2;
const CX = VB_WIDTH / 2;
const CY = VB_HEIGHT / 2;

const REACH = 340; // how far the pointer's influence extends (px)
const MAX_PUSH = 75; // how far the closest dots get shoved (px)

function pointerAt(t: number): { x: number; y: number } {
  // t in [0,1). Lissajous-style path with a small second harmonic for a more
  // organic, hand-driven feel. All frequencies are integers => seamless loop.
  const x =
    CX +
    Math.sin(TAU * 1 * t) * (VB_WIDTH * 0.4) +
    Math.sin(TAU * 3 * t + 1.3) * (VB_WIDTH * 0.07);
  const y =
    CY +
    Math.sin(TAU * 2 * t + 0.6) * (VB_HEIGHT * 0.4) +
    Math.sin(TAU * 5 * t + 2.1) * (VB_HEIGHT * 0.05);
  return { x, y };
}

export default function BackgroundDots() {
  const frame = useCurrentFrame();
  const t = (frame % durationInFrames) / durationInFrames;
  const p = pointerAt(t);

  return (
    <AbsoluteFill>
      <Img
        src={staticFile("assets/backgrounds/Back_Dark.png")}
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          objectFit: "cover",
        }}
      />
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${VB_WIDTH} ${VB_HEIGHT}`}
        preserveAspectRatio="xMidYMid slice"
        xmlns="http://www.w3.org/2000/svg"
        style={{ position: "relative", zIndex: 1 }}
      >
        {DOTS.map((d, i) => {
          const dx = d.x - p.x;
          const dy = d.y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          // Smooth Gaussian falloff: strongest at the pointer, ~0 past REACH.
          const influence = Math.exp(-(dist * dist) / (REACH * REACH));
          const push = MAX_PUSH * influence;
          const ux = dist > 0.001 ? dx / dist : 0;
          const uy = dist > 0.001 ? dy / dist : 0;
          return (
            <circle
              key={i}
              cx={d.x + ux * push}
              cy={d.y + uy * push}
              r={DOT_R}
              fill={DOT_COLOR}
            />
          );
        })}
      </svg>
    </AbsoluteFill>
  );
}
